def compare_versions(a: str, b: str) -> int:
    def parse_version(v: str):
        # Split off build metadata (after +)
        v = v.split('+')[0]

        # Split into version and pre-release
        if '-' in v:
            version_part, prerelease_part = v.split('-', 1)
            prerelease = prerelease_part.split('.')
        else:
            version_part = v
            prerelease = None

        # Parse major.minor.patch
        parts = version_part.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        return major, minor, patch, prerelease

    def compare_prerelease(pre_a, pre_b):
        # If both are None, they're equal
        if pre_a is None and pre_b is None:
            return 0
        # Version without pre-release has higher precedence
        if pre_a is None:
            return 1
        if pre_b is None:
            return -1

        # Compare pre-release identifiers one by one
        for i in range(max(len(pre_a), len(pre_b))):
            # More identifiers means higher precedence
            if i >= len(pre_a):
                return -1
            if i >= len(pre_b):
                return 1

            id_a = pre_a[i]
            id_b = pre_b[i]

            # Check if identifiers are numeric
            is_num_a = id_a.isdigit()
            is_num_b = id_b.isdigit()

            # Numeric identifiers compare numerically
            if is_num_a and is_num_b:
                num_a = int(id_a)
                num_b = int(id_b)
                if num_a < num_b:
                    return -1
                elif num_a > num_b:
                    return 1
            # Numeric identifier has lower precedence than non-numeric
            elif is_num_a and not is_num_b:
                return -1
            elif not is_num_a and is_num_b:
                return 1
            # Non-numeric identifiers compare in ASCII order
            else:
                if id_a < id_b:
                    return -1
                elif id_a > id_b:
                    return 1

        return 0

    major_a, minor_a, patch_a, pre_a = parse_version(a)
    major_b, minor_b, patch_b, pre_b = parse_version(b)

    # Compare major.minor.patch
    if major_a != major_b:
        return -1 if major_a < major_b else 1
    if minor_a != minor_b:
        return -1 if minor_a < minor_b else 1
    if patch_a != patch_b:
        return -1 if patch_a < patch_b else 1

    # Compare pre-release
    return compare_prerelease(pre_a, pre_b)
